function mirrorPathPairs(parent: number[], s: string): number {
  const n = parent.length;
  const adj: [number, number][][] = Array.from({ length: n }, () => []);
  for (let v = 1; v < n; v++) {
    const bit = 1 << (s.charCodeAt(v) - 97);
    adj[v].push([parent[v], bit]);
    adj[parent[v]].push([v, bit]);
  }
  let count = 0;
  for (let u = 0; u < n; u++) {
    const stack: [number, number, number][] = [[u, -1, 0]];
    while (stack.length) {
      const [v, from, m] = stack.pop()!;
      if (v > u && (m & (m - 1)) === 0) count++;
      for (const [w, bit] of adj[v]) if (w !== from) stack.push([w, v, m ^ bit]);
    }
  }
  return count;
}

