function mirrorPathPairs(parent: number[], s: string): number {
  const n = parent.length;
  const kids: number[][] = Array.from({ length: n }, () => []);
  for (let v = 1; v < n; v++) kids[parent[v]].push(v);
  const mask = new Array(n).fill(0);
  const order = [0];
  for (let i = 0; i < order.length; i++) {
    const v = order[i];
    for (const c of kids[v]) {
      mask[c] = mask[v] ^ (1 << (s.charCodeAt(c) - 97));
      order.push(c);
    }
  }
  const count = new Map<number, number>();
  let total = 0;
  for (const m of mask) {
    total += count.get(m) ?? 0;
    for (let b = 0; b < 26; b++) total += count.get(m ^ (1 << b)) ?? 0;
    count.set(m, (count.get(m) ?? 0) + 1);
  }
  return total;
}

